import json
from pathlib import Path
from collections import Counter, defaultdict

rows = [json.loads(l) for l in Path("logs/historical/pass_a/regrade.jsonl").read_text().splitlines() if l.strip()]
man = {r["instance_id"]: r for r in map(json.loads, Path("corpus/manifest.jsonl").read_text().splitlines() if False else [])}
# fix
man = {}
for line in Path("corpus/manifest.jsonl").read_text().splitlines():
    if line.strip():
        r = json.loads(line)
        man[r["instance_id"]] = r

print("=== by exit ===")
by_exit = defaultdict(list)
for r in rows:
    ex = [n for n in r["notes"] if n.startswith("exit=")]
    by_exit[ex[0] if ex else "?"].append(r)
for k,v in sorted(by_exit.items(), key=lambda kv: -len(kv[1])):
    miss_eq_req = 0
    failed_pos = 0
    for r in v:
        req = len(man[r["instance_id"]]["fail_to_pass"]) + len(man[r["instance_id"]]["pass_to_pass"])
        # unique
        reqs = list(dict.fromkeys(man[r["instance_id"]]["fail_to_pass"]+man[r["instance_id"]]["pass_to_pass"]))
        if len(r["missing"])==len(reqs) and not r["failed"]:
            miss_eq_req += 1
        if r["failed"]:
            failed_pos += 1
    print(f"{k:10} n={len(v):3d} all_required_missing={miss_eq_req:3d} has_failed={failed_pos:3d}")

print("\n=== exit=4 records ===")
for r in by_exit.get("exit=4", []):
    print(r["record_id"], "missing", len(r["missing"]), "failed", len(r["failed"]), "notes", r["notes"])

print("\n=== exit=-1 records ===")
for r in by_exit.get("exit=-1", []):
    print(r["record_id"], "sec", r["seconds"], "missing", len(r["missing"]), "failed", len(r["failed"]), "notes", r["notes"])

print("\n=== patch-failed ===")
for r in rows:
    if "patch-failed" in r["notes"]:
        print(r["record_id"], r["notes"], "missing", len(r["missing"]), "failed", len(r["failed"]))

print("\n=== empty-patch by exit ===")
c = Counter()
for r in rows:
    if "empty-patch" in r["notes"]:
        ex = [n for n in r["notes"] if n.startswith("exit=")][0]
        c[ex]+=1
print(c)

# per repo exit distribution
print("\n=== repo x exit ===")
rc = Counter()
for r in rows:
    repo = r["instance_id"].split(".")[0]
    ex = [n for n in r["notes"] if n.startswith("exit=")][0]
    rc[(repo, ex)] += 1
for k,v in sorted(rc.items()):
    print(f"  {k[0]:40} {k[1]:8} {v}")
