def norm(n):
    return ".".join(n.split("::")[1:])

# exact duplicate normalized names: count required ids that share a key
print("=== exact key collisions (required ids sharing normalize_node_id) ===")
total_ids=0
total_dups_ids=0
for inst in man:
    req=list(dict.fromkeys(inst["fail_to_pass"]+inst["pass_to_pass"]))
    by=defaultdict(list)
    for n in req:
        by[norm(n)].append(n)
    dups=[v for v in by.values() if len(v)>1]
    n_ids=sum(len(v) for v in dups)
    total_ids += len(req)
    total_dups_ids += n_ids
    if dups:
        print(f"  {inst['instance_id'].split('.')[-1]:20} req={len(req):4} colliding_ids={n_ids:3} keys={len(dups)}")
print("total required id occurrences", total_ids, "ids in a collision", total_dups_ids)

# substring: for each instance, how many required names are a proper substring of another required name
print("\n=== substring (shorter required name contained in a longer one) ===")
for inst in man:
    req=list(dict.fromkeys(inst["fail_to_pass"]+inst["pass_to_pass"]))
    names=sorted({norm(n) for n in req}, key=len)
    short=[]
    for a in names:
        for b in names:
            if a!=b and a in b:
                short.append(a)
                break
    if short:
        print(f"  {inst['instance_id'][:55]:55} shorter_names={len(short):3} e.g. {short[:4]}")
